import type { Core } from "@strapi/strapi";
import { PLUGIN_ID } from "../utils";

type Migration = Parameters<
  Core.Strapi["db"]["migrations"]["providers"]["internal"]["register"]
>[0];
type Transaction = Parameters<Migration["up"]>[0];
type Database = Parameters<Migration["up"]>[1];

interface OrphanForeignKey {
  table: string;
  column: string;
  referencedTable: string;
  onDelete: string;
}

const MAX_PASSES = 10;
const CHUNK_SIZE = 500;

const UID_PREFIX = `plugin::${PLUGIN_ID}.`;

/**
 * Whether the Better Auth content types declare foreign keys, i.e. the schema
 * was generated by a plugin version that adds them (`npx auth generate`).
 */
export const declaresForeignKeys = (strapi: Core.Strapi) =>
  Object.values(strapi.contentTypes).some(
    (contentType) =>
      contentType.uid.startsWith(UID_PREFIX) &&
      ((contentType as { foreignKeys?: unknown[] }).foreignKeys?.length ?? 0) >
        0,
  );

const getForeignKeys = (db: Database): OrphanForeignKey[] =>
  [...db.metadata.values()]
    .filter((meta) => meta.uid.startsWith(UID_PREFIX))
    .flatMap((meta) =>
      meta.foreignKeys.map((fk) => ({
        table: meta.tableName,
        column: fk.columns[0],
        referencedTable: fk.referencedTable,
        onDelete: (fk.onDelete ?? "CASCADE").toUpperCase(),
      })),
    );

/**
 * Applies a foreign key's ON DELETE action to rows whose column points at a row
 * that no longer exists. Returns the number of affected rows.
 */
const resolveOrphans = async (
  trx: Transaction,
  db: Database,
  fk: OrphanForeignKey,
): Promise<number> => {
  // Knex schema builders accumulate statements, so each check needs its own.
  const exists =
    (await db.getSchemaConnection(trx).hasTable(fk.table)) &&
    (await db.getSchemaConnection(trx).hasTable(fk.referencedTable)) &&
    (await db.getSchemaConnection(trx).hasColumn(fk.table, fk.column));
  if (!exists) return 0;

  const schema = db.getSchemaName();
  const tableOf = (table: string) =>
    schema ? trx(table).withSchema(schema) : trx(table);

  // withSchema applies to the joined table as well.
  const rows: Array<{ id: number }> = await tableOf(fk.table)
    .select(`${fk.table}.id`)
    .leftJoin(
      `${fk.referencedTable} as parent`,
      "parent.id",
      `${fk.table}.${fk.column}`,
    )
    .whereNotNull(`${fk.table}.${fk.column}`)
    .whereNull("parent.id");

  const ids = rows.map((row) => row.id);
  if (ids.length === 0) return 0;

  if (fk.onDelete !== "CASCADE" && fk.onDelete !== "SET NULL") {
    throw new Error(
      `[@strapi-community/plugin-better-auth] Found ${ids.length} row(s) in "${fk.table}" ` +
        `whose "${fk.column}" points at a missing "${fk.referencedTable}" row. ` +
        `The foreign key uses ON DELETE ${fk.onDelete}, so these rows can't be cleaned up ` +
        "automatically. Remove or fix them before starting Strapi.",
    );
  }

  for (let i = 0; i < ids.length; i += CHUNK_SIZE) {
    const query = tableOf(fk.table).whereIn("id", ids.slice(i, i + CHUNK_SIZE));

    if (fk.onDelete === "CASCADE") {
      await query.delete();
    } else {
      await query.update({ [fk.column]: null });
    }
  }

  strapi.log.info(
    `[@strapi-community/plugin-better-auth] ${fk.onDelete === "CASCADE" ? "Deleted" : "Detached"} ` +
      `${ids.length} orphaned row(s) in "${fk.table}" (missing "${fk.referencedTable}" via "${fk.column}").`,
  );

  return ids.length;
};

/**
 * Removes rows that would violate the Better Auth foreign keys, so the schema
 * sync that follows can add them. Before the foreign keys existed, deleting a
 * row (e.g. an organization through the dashboard) could leave rows behind that
 * point at it. Postgres and MySQL refuse to add a constraint while such rows
 * exist, and SQLite would silently keep them.
 *
 * Runs until nothing changes, as cleaning up one table can orphan rows in
 * another (e.g. a team whose organization is gone, then that team's members).
 */
export const removeOrphanedRows: Migration = {
  name: `${PLUGIN_ID}::1.0.0-remove-orphaned-rows`,
  async up(trx, db) {
    const foreignKeys = getForeignKeys(db);

    for (let pass = 0; pass < MAX_PASSES; pass++) {
      let affected = 0;

      for (const fk of foreignKeys) {
        affected += await resolveOrphans(trx, db, fk);
      }

      if (affected === 0) return;
    }
  },
  async down() {},
};
